});

test('sem versão usa o padrão 1.0.0', () => {
  assert.deepEqual(montarPackageJson('meu-app'), {
    name: 'meu-app',
    version: '1.0.0',
    type: 'module',
  });
});

test('nome vazio lança erro', () => {
  assert.throws(() => montarPackageJson('', '1.0.0'));
});

test('nome ausente lança erro', () => {
  assert.throws(() => montarPackageJson(undefined, '1.0.0'));
});

solutionCode:
export function montarPackageJson(nome, versao) {
  if (nome === undefined || nome === '') {
    throw new Error('nome do pacote é obrigatório');
  }
  if (versao === undefined) {
    versao = '1.0.0';
  }
  return { name: nome, version: versao, type: 'module' };
}
